def spiral_cells(rows, cols, ks):
    def before(t):
        return rows * cols - (rows - 2 * t) * (cols - 2 * t)
    last = (min(rows, cols) - 1) // 2
    out = []
    for k in ks:
        lo, hi = 0, last
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if before(mid) < k:
                lo = mid
            else:
                hi = mid - 1
        t = lo
        p = k - before(t) - 1
        h, w = rows - 2 * t, cols - 2 * t
        if p < w:
            out.append([t, t + p])
        elif p < w + h - 1:
            out.append([t + p - w + 1, t + w - 1])
        elif p < 2 * w + h - 2:
            out.append([t + h - 1, t + w - 1 - (p - w - h + 2)])
        else:
            out.append([t + h - 1 - (p - 2 * w - h + 3), t])
    return out

